import { createWhichCommand, createWhichCommands } from './dist/commands/which/index.js';
import type { CommandContext, CommandDefinition, CommandResult } from './dist/contracts/index.js';
const singular: CommandDefinition = createWhichCommand();
const definitions: readonly CommandDefinition[] = createWhichCommands();
declare const context: CommandContext;
const result: CommandResult | Promise<CommandResult> = singular.execute(context);
void definitions; void result;
// @ts-expect-error declared singleton collection is readonly
createWhichCommands().push(singular);

import { whichCommands, createWhichCommand, type WhichCommandsOptions } from './dist/commands/which/index.js';
import type { VirtualShellPlugin } from './dist/contracts/index.js';
const options: WhichCommandsOptions = { replace: true, limits: { maxProbes: 1 } };
const plugin: VirtualShellPlugin = whichCommands(options);
createWhichCommand(options); void plugin;
// @ts-expect-error readonly option
options.replace = false;
// @ts-expect-error no invented profile/host fallback option
whichCommands({ hostFallback: true });
// @ts-expect-error boolean replacement policy
whichCommands({ replace: 'yes' });

import { createWhichCommand, type WhichCommandsOptions, type WhichLimits } from './dist/commands/which/index.js';
const limits: WhichLimits = { maxArguments: 4096, maxArgumentBytes: 65536, maxPathEnvBytes: 65536, maxPathComponents: 4096, maxPathBytes: 16384, maxProbes: 65536, maxOutputBytes: 8388608 };
const options: WhichCommandsOptions = { limits };
createWhichCommand(options); createWhichCommand({ limits: { maxOutputBytes: 1 } });
// @ts-expect-error readonly limits
limits.maxProbes = 2;
// @ts-expect-error numeric limit
createWhichCommand({ limits: { maxProbes: '2' } });
// @ts-expect-error closed known limit names
createWhichCommand({ limits: { maxCommands: 1 } });
// @ts-expect-error full limits declaration requires all seven keys
const incomplete: WhichLimits = { maxProbes: 1 };
void incomplete;

import { createWhichCommand } from './dist/commands/which/index.js';
import type { CommandContext, CommandHandler, CommandResult, ByteSink, ByteSource, FileSystem } from './dist/contracts/index.js';
declare const fs: FileSystem; declare const stdin: ByteSource; declare const stdout: ByteSink; declare const stderr: ByteSink; declare const signal: AbortSignal;
const context: CommandContext = { command: 'which', args: ['tool'], cwd: '/', env: { PATH: '/a' }, fs, stdin, stdout, stderr, signal };
const handler: CommandHandler = createWhichCommand().execute;
const result: CommandResult | Promise<CommandResult> = handler(context); void result;
// @ts-expect-error command cancellation signal remains readonly
context.signal = new AbortController().signal;
// @ts-expect-error byte sink does not accept strings
stdout.write('not bytes');
